scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap016hemei == 0) @Talk0;
	If ($Talkmap016hemei == 1) @Talk1;
	If ($Talkmap016hemei == 2) @Talk2;
	If ($Talkmap016hemei == 3) @Talk3;
	Return;
@Talk0:	
	Say("何梅：独孤公子是哪里人？", 66);
	Say("独孤剑：我自幼父母双亡，被师傅带回衡山抚育成人。", 1);
	Assign($Talkmap016hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子可有兄弟姊妹？", 66);
	Say("独孤剑：我有许多同门学艺的师弟师妹。", 1);
	Assign($Talkmap016hemei, 2);
	Return;
@Talk2:	
	Say("何梅（害羞的）：独孤公子是否……是否已成家立室？", 66);
	Say("独孤剑：我乃一江湖草莽之人，过着一种刀光剑影、四处飘摇的生活，寻常女子怎愿与我相伴？况且我也不想误人青春。", 1);
	Say("何梅：……", 66);
	Assign($Talkmap016hemei, 3);
	Return;
@Talk3:	
	Say("独孤剑：何姑娘家住哪里？", 1);
	Say("何梅：我家住在城北，就在官衙的后面。", 66);
	Return;

scripts.贾老实对话.txt:
//和贾老实的对话

	If($Event << 90) @Eventlessthan90;
	If($Event == 95) @Event95;
	If($Event == 100) @Event100;
	If($Event == 110) @Event110;
	If($Event == 120) @Event120;
	If($Event == 180) @Event180;

    Say("贾老实：有生意好说，没生意勿扰。", 207);
  	Return;

@Eventlessthan90:
	GetRandNum($TalkJia, 0, 2);
	If($TalkJia == 0) @TalkJia0;
	If($TalkJia == 1) @TalkJia1;
	If($TalkJia == 2) @TalkJia2;
@TalkJia0:
	Say("贾老实：想找个乡下人做点无本生意，找了半天一个呆瓜也没找到。", 207);
	Return;
@TalkJia1:	
	Say("贾老实：我带你去一个很好玩的地方玩玩，好不好？那儿有好多姑娘呢。", 207);
	Say("独孤剑：我还有事。", 2);
	Say("贾老实：我又不要你的银子，只要你给我买三壶酒就行了。", 207);
	Return;
@TalkJia2:
	Say("贾老实：不做生意就不要来烦我。", 207);
	Return;

	
@Event95:
	Say("贾老实：我叫贾老实，货真价实的“假老实”，所以我从来不做亏本生意。", 207);
	Say("独孤剑：听说渔村的老王和你交情非同寻常。", 1);
	Say("贾老实：那自然，我对他有救命之恩，我叫他干啥他就干啥。", 207);
	Say("独孤剑：我想请老王出一趟海去救一个人，你能帮忙吗？", 1);
	Say("贾老实：我帮了你，有什么好处？", 207);
	Say("独孤剑：银子我还是有一些的。", 1);
	Say("贾老实：银子是什么东西？银子是王八蛋，生不带来，死不带去，我不希罕。", 207);
	Say("独孤剑：那你要……", 8);
	Say("贾老实：告诉你，我从来没做过亏本生意，就是因为我从来不和别人用银子算帐。", 207);
	Say("独孤剑：救人要紧，你要什么好处？", 1);
	Say("贾老实：我要一样东西。一样常人不能得到的东西。", 207);
	Say("独孤剑：说说看，看我能否找到。", 1);
	Say("贾老实：听说怡春院里的南宫彩虹姑娘貌若天仙，且奇香无比，我想要她一滴眼泪。", 207);
	Say("独孤剑：这，太强人所难了吧?", 8);
	Say("贾老实：你看着办吧，就是这个条件。", 207);
	Memo("回到临安城，在客栈一楼找到贾老实，他要求得到怡春院南宫彩虹的一滴眼泪才肯帮忙。");
	Assign($Event, 100);
	Return;


@Event100:	
	Say("贾老实：你看着办吧，就是这个条件。", 207);
	Return;


@Event110:
	Say("独孤剑：这就是你要的南宫彩虹小姐的眼泪。", 1);
	Say("贾老实：哈哈，果然是南宫小姐的眼泪！传说这泪水有西域曼陀罗花的香味，那是南宫小姐特有的味道，今日一闻，果然是真。你一定见到南宫小姐了，她果真是沉鱼落雁之容，羞花闭月之貌？如此绝代佳人，如果我能够见他一面，死而无怨啊，呜，呜……", 207);     
	Say("独孤剑：麻烦大叔快些让老王出海吧。", 2);
	Say("贾老实：好啦好啦，走吧。", 207);
	StopMusic();
	PlayMusic("春潮.mp3");
	DelGoods("Goods404_一杯清水.ini");
	SetNpcKind("贾老实", 3);
	SetNpcRelation("贾老实", 2);
	Assign($Event, 120);
	Memo("回到客栈找到贾老实，用清水骗过他后，两人一起前往海边小渔村。");
	Return;

@Event120:
	Say("贾老实：走吧。", 207);
	Return;

@Event180:
	Say("贾老实：你居然回来了？而且还是活的，真不可想象。", 207);
	Return;

